Testing:
func TestTable(t *testing.T) {
    tests := []struct {
        input int
        want  int
    }{
        {1, 2},
        {3, 4},
    }
    for _, tc := range tests {
        got := f(tc.input)
        if got != tc.want {
            t.Errorf("got %d, want %d", got, tc.want)
        }
    }
}  // table-driven test

func ExampleAdd() {
    fmt.Println(Add(1, 2))
    // Output: 3
}  // example test (also generates docs)

func BenchmarkX(b *testing.B) {
    for i := 0; i < b.N; i++ {
        doWork()
    }
}  // benchmark (go test -bench=.)

b.RunParallel(func(pb *testing.PB) {
    for pb.Next() {
        work()
    }
})  // parallel benchmark

