Decorators:
@property
    def name(self):
        return self._name  // computed attribute access

@name.setter
    def name(self, val):
        self._name = val  // property setter

@name.deleter
    def name(self):
        del self._name  // property deleter

@staticmethod
    def f(x):
        return x  // static method (no self)

@classmethod
    def f(cls, x):
        return x  // class method receives cls

@functools.lru_cache(maxsize=128)
    def f(x):
        return x  // memoization decorator

@functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)  // preserves metadata in wrapper

@abc.abstractmethod
    def f(self):
        pass  // declares abstract method

