Pattern Matching:
match x {
    1 => "one",
    2 => "two",
    _ => "other"
}  // basic match

match x {
    1 | 2 => "one or two",
    3..=5 => "three to five",
    _ => "other"
}  // OR and range patterns

match x {
    n if n > 5 => "big",
    _ => "small"
}  // match guard

match opt {
    Some(x) if x > 0 => x,
    _ => 0
}  // match guard on enum variant

match pair {
    (0, y) => y,
    (x, 0) => x,
    _ => 0
}  // destructuring tuple

match p {
    Point { x, y } => x + y
}  // destructuring struct

match val {
    Some(x) => x,
    None => 0
}  // destructuring enum

match arr {
    [a, b, c] => a + b + c
}  // destructuring array/slice

match x {
    n @ 1..=10 => n,
    _ => 0
}  // @ binding (value + pattern)

match x {
    Some(ref r) => println!("{}", r)
}  // ref pattern (borrows inner value)

match x {
    Some(ref mut r) => *r = 42
}  // ref mut pattern

match s.as_str() {
    "hello" => println!("hi")
}  // string literal pattern

match x {
    .. => {}
}  // rest pattern (ignore rest of fields)

