Traits:
trait Display {
    fn fmt(&self) -> String
}  // trait declaration

impl Display for Point {
    fn fmt(&self) -> String {
        format!("({},{})", self.x, self.y)
    }
}  // implementing a trait

trait Iter {
    type Item;
    fn next(&mut self) -> Option<Self::Item>;
}  // trait with associated type

impl<T> Iter for MyIter<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> { None }
}  // implementing associated type

trait Default {
    fn default() -> Self;
}  // marker traits (no methods)

