  format!("Hello {}", name)
}
fn main() {
  let name = String::from("Doge");
  println!("{}", greet(name));
}

rs.solution:
fn greet(name: &str) -> String {
  format!("Hello {}", name)
}
fn main() {
  let name = String::from("Doge");
  println!("{}", greet(&name));
}

