  format!("Hello {}", name)
}
fn main() {
  println!("{}", greet("Doge"));
}

rs.solution:
fn greet(name: &str) -> String {
  format!("Hello {}", name)
}
fn main() {
  println!("{}", greet("Doge"));
}

rs.bug:
fn greet(name: &str) -> String {
  format!("Hello {}", name)
}
fn main() {
  let name = String::from("Doge");
  println!("{}", greet(name));
}

rs.solution:
fn greet(name: &str) -> String {
  format!("Hello {}", name)
}
fn main() {
  let name = String::from("Doge");
  println!("{}", greet(&name));
}

