backend.solution:
function stripCircular(obj, seen = new WeakSet()) {
  if (typeof obj !== 'object' || obj === null) return obj;
  if (seen.has(obj)) return '[Circular]';
  seen.add(obj);
  if (Array.isArray(obj)) return obj.map(v => stripCircular(v, seen));
  const result = {};
  for (const [key, value] of Object.entries(obj)) {
    result[key] = stripCircular(value, seen);
  }
  return result;
}

app.get('/api/user', (req, res) => {
  res.json(stripCircular(user));
});

