const mutex = new Map();

async function getUser(id) {
  let user = await cache.get(`user:${id}`);
  if (user) return user;

  // Mutex to prevent stampede
  if (!mutex.has(id)) {
    mutex.set(id, (async () => {
      const user = await db.query('SELECT * FROM users WHERE id = ?', [id]);
      await cache.set(`user:${id}`, user, 'EX', 3600);
      return user;
    })());
  }

  try {
    return await mutex.get(id);
  } finally {
    mutex.delete(id);
  }
}

