scala.bug:
import scala.annotation.tailrec

object Main extends App {
  @tailrec
  def factorial(n: Int): Int = {
    if (n <= 1) 1
    else n * factorial(n - 1)
  }
  println(factorial(5))
}

scala.solution:
import scala.annotation.tailrec

object Main extends App {
  @tailrec
  def factorial(n: Int, acc: Int = 1): Int = {
    if (n <= 1) acc
    else factorial(n - 1, n * acc)
  }
  println(factorial(5))
}

