What is a Compiler?.code:
// The compilation pipeline stages:
// 1. Source Code → Lexer → Tokens
// 2. Tokens → Parser → AST (Abstract Syntax Tree)
// 3. AST → Semantic Analysis → Validated AST
// 4. Validated AST → Code Generator → Output Code
// 5. Output Code → Execution → Result

// Example: A simple addition in C
int result = 5 + 3;
//           ^^^^^^^
//     Binary expression: operator '+'
//     Left operand: 5 (Literal)
//     Right operand: 3 (Literal)

Lexical Analysis.code:
// Tokenization example:
// Input:  let count = 5 + 3;
//
// Tokens produced:
// [KEYWORD]  "let"
// [IDENT]    "count"
// [OPERATOR] "="
// [NUMBER]   "5"
// [OPERATOR] "+"
// [NUMBER]   "3"
// [PUNCT]    ";"

// Different languages, same token types:
// Python:    count = 5 + 3
// Go:        var count int = 5 + 3
// Rust:      let mut count = 5 + 3;
// SQL:       SELECT count + 3 FROM table;

Syntax Analysis.code:
// Write code and click AST ▶ to see the tree
function greet(name) {
  const message = "Hello, " + name;
  return message;
}

// Expected AST structure:
// Program
//   FunctionDeclaration: "greet"
//     Block
//       VariableDeclaration: "message"
//       ReturnStatement
//         BinaryExpression: +
//           Identifier: "name"

Generating Output.code:
// Code generation walkthrough:
// Input AST:
//   Program
//     VariableDeclaration: "total"
//       BinaryExpression: +
//         Number: 10
//         Number: 20

// Generated JavaScript:
let total = 10 + 20;

// With constant folding optimization:
let total = 30;  // 10+20 computed at compile time!

All Languages Supported.code:
// Try these examples in different languages:

// Python
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

// Go
func greet(name string) string {
    return "Hello, " + name
}

// Rust
fn factorial(n: u32) -> u32 {
    match n {
        0 => 1,
        _ => n * factorial(n - 1)
    }
}

// SQL
SELECT users.name, COUNT(orders.id)
FROM users
LEFT JOIN orders ON users.id = orders.user_id
GROUP BY users.name;

Type Checking & Scope.code:
// Semantic analysis catches these:
// Type mismatch (TypeScript):
// let age: number = "twenty";  // Error: Type 'string' not assignable to 'number'

// Undefined variable (all languages):
// console.log(undeclaredVar);  // ReferenceError: undeclaredVar is not defined

// Scope error:
// {
//   let x = 1;
// }
// console.log(x);  // ReferenceError: x is not defined (block scoped)

// Type error caught by compiler:
// In Go: var x int = "hello"  // cannot use "hello" (type string) as type int

Making Code Faster.code:
// Before optimization:
function compute(arr) {
  let total = 0;
  for (let i = 0; i < arr.length; i++) {
    const taxRate = 0.08;
    total += arr[i] * taxRate;
  }
  return total;
}

// After constant propagation + inlining:
// const taxRate = 0.08;  // hoisted outside loop
// total += arr[i] * 0.08;  // constant propagated

// After loop-invariant code motion:
// const taxRate = 0.08;
// const len = arr.length;  // computed once
// for (let i = 0; i < len; i++) {
//   total += arr[i] * taxRate;
// }

From AST to Machine Code.code:
// High-level source:
// result = (a + b) * (c - d)

// Three-Address Code (TAC):
// t1 = a + b
// t2 = c - d
// result = t1 * t2

// SSA Form (Static Single Assignment):
// t1 = a + b
// t2 = c - d
// t3 = t1 * t2
// result = t3
// (each variable assigned exactly once)

// LLVM IR (conceptual):
// %t1 = add i32 %a, %b
// %t2 = sub i32 %c, %d
// %result = mul i32 %t1, %t2

